<body>
    <div id="gameContainer">
        <h1>🐍 SNAKE GAME 🐍</h1>
        <div id="scoreBoard">Score: 0</div>
        <canvas id="gameCanvas" width="600" height="600"></canvas>

        <div id="startMenu" class="menu">
            <h2>🐍 SNAKE GAME 🐍</h2>
            <button id="btn1v1">1 Player vs 1 Player</button>
            <button id="btn1v2">1 Player vs CPU</button>
            <button id="btn2v2">CPU vs CPU</button>
            <div class="instructions">
                <p>🎮 Use Arrow Keys or WASD to move</p>
                <p>🔄 Press any key to restart</p>
            </div>
        </div>

        <div id="gameOverMenu" class="menu hidden">
            <h2>GAME OVER</h2>
            <h2 id="finalScore" style="color: #e94560;"></h2>
            <button id="restartBtn">Play Again</button>
            <button id="backToMenuBtn">Main Menu</button>
        </div>
    </div>

    <script>
        const canvas = document.getElementById('gameCanvas');
        const ctx = canvas.getContext('2d');

        const GRID = 30;
        const COLS = canvas.width / GRID;
        const ROWS = canvas.height / GRID;
        const FPS = 10;

        // State
        let gameMode = '1v1'; // '1v1', '1v2', '2v2'
        let running = false;
        let gameOver = false;
        let snake1, snake2, food, direction, nextDirection, speed;
        let score1, score2;
        let lastTime = 0;

        // Directions
        const DIR = {
