                if (gameMode === '1v1' || gameMode === '2v2') {
                    if (direction !== DIR.UP) nextDirection = DIR.DOWN;
                }
            } else if (key === 'arrowleft' || key === 'a') {
                if (gameMode === '1v1' || gameMode === '2v2') {
                    if (direction !== DIR.RIGHT) nextDirection = DIR.LEFT;
                }
            } else if (key === 'arrowright' || key === 'd') {
                if (gameMode === '1v1' || gameMode === '2v2') {
                    if (direction !== DIR.LEFT) nextDirection = DIR.RIGHT;
                }
            }
        });

        // CPU AI
        function cpuMove(snake, food) {
            // Try to move toward food
            const head = snake[0];
            const dx = food.x - head.x;
            const dy = food.y - head.y;

            // Find a valid direction that moves toward food
            const candidates = [
                { dir: DIR.UP, dx: 0, dy: -1 },
                { dir: DIR.DOWN, dx: 0, dy: 1 },
                { dir: DIR.LEFT, dx: -1, dy: 0 },
                { dir: DIR.RIGHT, dx: 1, dy: 0 }
            ];

            // Score each candidate
            candidates.sort((a, b) => {
                const scoreA = a.dx * dx + a.dy * dy;
                const scoreB = b.dx * dx + b.dy * dy;
                return scoreB - scoreA;
            });

            // Filter out directions that collide with snake body
            const filtered = candidates.filter(c => {
                const nx = head.x + c.dx;
                const ny = head.y + c.dy;
                return !snake.some(seg => seg.x === nx && seg.y === ny && seg !== head);
            });

            if (filtered.length > 0) {
                return filtered[0].dir;
            }
            // Fallback: try any direction
            return candidates[0].dir;
        }

        function restartGame() {
