                ctx.fillRect(seg.x * GRID, seg.y * GRID, GRID - 1, GRID - 1);
            });

            // Snake 2
            snake2.forEach((seg, i) => {
                ctx.fillStyle = i === 0 ? '#e94560' : '#c92a60';
                ctx.fillRect(seg.x * GRID, seg.y * GRID, GRID - 1, GRID - 1);
            });

