            ctx.textAlign = 'right';
            ctx.fillText(`Player 2: ${score2}`, canvas.width - 10, 25);
        }

        // Buttons
        document.getElementById('btn1v1').addEventListener('click', () => {
            gameMode = '1v1';
            document.getElementById('startMenu').classList.add('hidden');
            restartGame();
        });

        document.getElementById('btn1v2').addEventListener('click', () => {
            gameMode = '1v2';
            document.getElementById('startMenu').classList.add('hidden');
